/*
 * Terminology migration: 鲁棒 -> 抗干扰.
 *
 * The replacement is NOT a plain find-and-replace, for three reasons this script encodes:
 *
 *  1. 鲁棒性 must become 抗干扰能力, not 抗干扰性. The longer pattern is therefore applied first.
 *
 *  2. tech.html is GENERATED by scripts/gen-tech-html.js, and all seven of its occurrences come
 *     from that generator. Editing only the output would be undone by the next generation, so the
 *     generator is in the target set as well.
 *
 *  3. scripts/rename-project.js holds a rule table whose TARGET is the old wording. Left alone it
 *     is a landmine: re-running that migration would inject 鲁棒 back into the HTML pages. Its
 *     target is updated here so the tool stays correct rather than historical.
 *
 * Deliberately NOT touched (see the phase-14 report for the full justification):
 *   docs/reports/**          frozen development history - rewriting it would falsify the record
 *   scripts/out/rename-log.json   a generated audit trail of the earlier rename
 *
 * Usage: node scripts/apply-terminology.js [--apply]
 */
'use strict';
const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');
const APPLY = process.argv.includes('--apply');

const RULES = [
  ['鲁棒性', '抗干扰能力'],   // longest first, or 鲁棒性 degrades into 抗干扰性
  ['鲁棒', '抗干扰']
];

/** Files in scope: the documents, the page markup, JS comments, CSS comments, and the generators. */
function targets() {
  const out = ['README.md', 'index.html', 'embed-image.html', 'extract-image.html', 'tech.html'];
  for (const dir of ['js', 'css']) {
    const walk = (d) => {
      for (const e of fs.readdirSync(d, { withFileTypes: true })) {
        const p = path.join(d, e.name);
        if (e.isDirectory()) walk(p);
        else if (/\.(js|css)$/.test(e.name)) out.push(path.relative(ROOT, p).replace(/\\/g, '/'));
      }
    };
    if (fs.existsSync(path.join(ROOT, dir))) walk(path.join(ROOT, dir));
  }
  /*
   * Tools whose rule tables or assertions name the term on purpose are NOT migration targets.
   * check-readme.js in particular must keep 鲁棒 in scope: rewriting it would flip its assertion
   * from "the term is absent" to "抗干扰 is absent", which is the opposite of the intent. The
   * dry run caught exactly that before it could be applied.
   */
  for (const f of ['gen-tech-html.js', 'rename-project.js', 'patch-appjs.js', 'apply-nav.js',
    'nav-partial.js', 'gen-paper-figures.js', 'tech-html-parts.js', 'list-tests.js',
    'move-reports.js']) {
    out.push('scripts/' + f);
  }
  return out;
}

let files = 0, total = 0;
const log = [];
for (const rel of targets()) {
  const abs = path.join(ROOT, rel);
  if (!fs.existsSync(abs)) continue;
  const before = fs.readFileSync(abs, 'utf8');
  let after = before;
  const changes = [];
  for (const [from, to] of RULES) {
    const n = after.split(from).length - 1;
    if (!n) continue;
    after = after.split(from).join(to);
    changes.push({ from, to, count: n });
  }
  if (!changes.length) continue;
  files++;
  const n = changes.reduce((a, c) => a + c.count, 0);
  total += n;
  log.push({ file: rel, changes });
  console.log(`${rel}`);
  for (const c of changes) console.log(`    ${c.count} x  "${c.from}" -> "${c.to}"`);
  if (APPLY) fs.writeFileSync(abs, after, 'utf8');
}

console.log(`\n${files} file(s), ${total} replacement(s)` + (APPLY ? ' - written' : ' (dry run)'));
if (APPLY) {
  fs.mkdirSync(path.join(ROOT, 'scripts', 'out'), { recursive: true });
  fs.writeFileSync(path.join(ROOT, 'scripts', 'out', 'terminology-log.json'),
    JSON.stringify({ appliedAt: new Date().toISOString(), rules: RULES, files, total, log }, null, 2));
  console.log('-> scripts/out/terminology-log.json');
}

// ---------------------------------------------------------------- verification
/*
 * Exempt from the sweep:
 *   docs/reports/**      frozen development history
 *   scripts/out/**       generated audit logs (the rename log, and this run's own log)
 *   the two tools whose PURPOSE requires naming the term: this script's rule table, and
 *   check-readme.js, whose job is to assert the term is absent - a check cannot assert the
 *   absence of a string it is not allowed to contain.
 */
const skip = /^(docs[\\/]reports|scripts[\\/]out)([\\/]|$)|^scripts[\\/](apply-terminology|check-readme)\.js$/;
function residual() {
  const found = [];
  const walk = (d) => {
    for (const e of fs.readdirSync(d, { withFileTypes: true })) {
      const p = path.join(d, e.name);
      const rel = path.relative(ROOT, p).replace(/\\/g, '/');
      if (skip.test(rel)) continue;
      if (e.isDirectory()) { if (!/^(node_modules|\.research|downloads|\.git)$/.test(e.name)) walk(p); continue; }
      if (!/\.(md|html|js|css|json)$/.test(e.name)) continue;
      const s = fs.readFileSync(p, 'utf8');
      const n = s.split('鲁棒').length - 1;
      if (n) found.push({ file: rel, count: n });
    }
  };
  walk(ROOT);
  return found;
}
const left = residual();
console.log(`\nresidual 鲁棒 outside docs/reports/ and scripts/out/ : ${left.length} file(s)`);
for (const f of left) console.log(`  !! ${f.file}  x${f.count}`);
if (left.length) process.exitCode = 1;
